// Reads the review tab. Wrong drawing = column F says 'no' (any case). Everything else is only counted.
const res = $input.first().json;
if (res.error || !Array.isArray(res.values)) {
  return [{ json: { reviewOk: false, error: JSON.stringify(res.error || res).slice(0, 300), wrong: [] } }];
}
const rows = res.values.slice(1);
const norm = (s) => String(s ?? '').trim();
const counts = { rows: 0, yes: 0, no: 0, blank: 0, other: 0 };
const cfg = $('Config').first().json;
const onlyTabs = String(cfg.tabs || '').split(',').map(x => x.trim()).filter(Boolean);
const want = String(cfg.mode || '').toLowerCase() === 'yes' ? 'yes' : 'no'; // mode 'yes' = report on the correct drawings, never changes anything
const includeNoted = cfg.includeNoted === true || want === 'yes';
// Rows whose note names the wrong products: 'drawing file:SKU,SKU;drawing file:SKU' -> only those products are treated as wrong (not the whole drawing).
const overrides = {};
String(cfg.noteSkus || '').split(';').map(x => x.trim()).filter(Boolean).forEach(x => { const [r, l] = x.split(':'); if (r && l) overrides[r.trim().toLowerCase()] = l.split(/[,\s]+/).map(v => v.toUpperCase()).filter(Boolean); });
const wrong = [], held = [];
rows.forEach((r, i) => {
  const rawTab = norm(r[0]);
  const tab = rawTab.replace(/^.*?:\s*/, '').trim(); // 'CHECK ONE PRODUCT: Bathtub' -> 'Bathtub'
  const file = norm(r[1]);
  if (!tab && !file) return;
  counts.rows++;
  const f = norm(r[5]).toLowerCase();
  if (f === 'yes') counts.yes++; else if (f === 'no') counts.no++; else if (!f) counts.blank++; else counts.other++;
  if (f === want) {
    // Single-product check rows ('CHECK ONE PRODUCT: <tab>') name the drawing in B but the product in E: only that product is meant.
    const single = /^CHECK ONE PRODUCT/i.test(rawTab) || !/\.[A-Za-z0-9]{2,5}$/.test(file);
    const skuText = /^CHECK ONE PRODUCT/i.test(rawTab) ? norm(r[4]) : file;
    const item = { reviewRow: i + 2, tab, rawTab, file, isFile: !single, skus: single ? skuText.split(/[,;\s]+/).map(x => x.toUpperCase()).filter(x => /^[A-Z]{2,}\d+/.test(x)) : [], products: norm(r[2]), size: norm(r[3]), note: norm(r[6]) };
    if (onlyTabs.length && !onlyTabs.includes(tab)) { item.reason = 'tab not in Config.tabs'; held.push(item); }
    else if (overrides[file.toLowerCase()] && want === 'no') { item.isFile = false; item.skus = overrides[file.toLowerCase()]; item.reason = 'note: only these products'; wrong.push(item); }
    else if (item.note && !includeNoted) { item.reason = 'has a note: may be one product or a size problem, not the whole drawing'; held.push(item); }
    else wrong.push(item);
  }
});
return [{ json: { reviewOk: true, counts, wrong, held } }];

// Only the tabs named in the review's column A are read.
const w = $('Parse Review').first().json.wrong || [];
const ALL = ['2026Instock','Animal','Balustrade','Bathtub','Bench','BookMatchedSlabs','Carving','Columns','DoorSurround','Exterior-Wall-Decoration','Fireplace','Fountain','Lamppost','Marble+ Basin','Marble+ ConsoleTable','MarbleMedallion','MarbleRangeHood','MarbleSlab','Moulding','OutdoorCornice','Planter','Sink','Stairs','Statue','StoneMosaicTile','Table','Vanity','Wainscoting','Wall-Coverings','WindowSurround'];
const tabs = [...new Set(w.map(x => x.tab).filter(t => ALL.includes(t)))];
return tabs.map(sheet_name => ({ json: { sheet_name } }));

// Columns needed: Product No., the Shopify admin link, IMAGE URL11 and CAD Drawing URL (with their column letters, to clear them later).
const DOC = '1ITSJNL7iql08AklUOLI1QSpOO0HlYEb8Dui0eNBXSeI';
const SHEET = $('Loop Through Sheets').first().json.sheet_name;
const headers = ($input.first().json.values?.[0] || []).map(h => String(h ?? '').trim());
const NEEDED = ['Product No.', 'Shopify_Update_product_URL', 'IMAGE URL11', 'CAD Drawing URL'];
const letters = (n) => { let s = ''; n += 1; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; };
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;
const cols = NEEDED.map(name => ({ name, idx: headers.lastIndexOf(name) })).filter(c => c.idx >= 0).map(c => ({ ...c, letter: letters(c.idx) }));
const ranges = cols.length ? cols.map(c => `${q(SHEET)}!${c.letter}3:${c.letter}`) : [`${q(SHEET)}!A2:A2`];
const url = `https://sheets.googleapis.com/v4/spreadsheets/${DOC}/values:batchGet?majorDimension=COLUMNS&valueRenderOption=FORMATTED_VALUE&` + ranges.map(r => 'ranges=' + encodeURIComponent(r)).join('&');
return [{ json: { sheet_name: SHEET, cols, url, hasUrlCol: cols.some(c => c.name === 'Shopify_Update_product_URL') } }];

// Finds, in this tab, the products whose IMAGE URL11 or CAD Drawing URL is one of the wrong drawings (exact file name; a _uuid copy suffix is ignored).
const plan = $('Plan Columns').first().json;
const wrong = $('Parse Review').first().json.wrong.filter(w => w.tab === plan.sheet_name);
const vr = $input.first().json.valueRanges || [];
const col = {}; plan.cols.forEach((c, i) => { col[c.name] = vr[i]?.values?.[0] || []; });
const letterOf = {}; plan.cols.forEach(c => { letterOf[c.name] = c.letter; });
const baseUrl = (u) => String(u || '').split('?')[0];
const nameOf = (u) => { const l = baseUrl(u).split('/').pop() || ''; try { return decodeURIComponent(l); } catch (e) { return l; } };
const UUID = /_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(?=\.[A-Za-z0-9]+$)/i;
const base = (n) => String(n).replace(UUID, '').toLowerCase();
const byFile = new Map(); const bySku = new Map();
wrong.forEach(w => { if (w.isFile) byFile.set(base(w.file), w); else w.skus.forEach(s => bySku.set(s, w)); });
const stats = { tab: plan.sheet_name, wrongDrawings: wrong.length, rows: 0, affected: 0, noShopifyUrl: 0 };
const nRows = Math.max(0, ...Object.values(col).map(a => a.length));
const prods = [], sheetOnly = [];
for (let i = 0; i < nRows; i++) {
  const sku = String((col['Product No.'] || [])[i] ?? '').trim();
  const adm = String((col['Shopify_Update_product_URL'] || [])[i] ?? '');
  const u11 = String((col['IMAGE URL11'] || [])[i] ?? '').trim();
  const cad = String((col['CAD Drawing URL'] || [])[i] ?? '').trim();
  if (!sku) continue;
  stats.rows++;
  const m11 = u11 && byFile.get(base(nameOf(u11))), mCad = cad && byFile.get(base(nameOf(cad)));
  const w = m11 || mCad || bySku.get(sku.toUpperCase());
  if (!w) continue;
  stats.affected++;
  const clear = [];
  const isSkuRow = !w.isFile;
  if (m11 || (isSkuRow && u11)) clear.push({ cell: `'${plan.sheet_name.replace(/'/g, "''")}'!${letterOf['IMAGE URL11']}${i + 3}`, column: 'IMAGE URL11' });
  if (mCad || (isSkuRow && cad)) clear.push({ cell: `'${plan.sheet_name.replace(/'/g, "''")}'!${letterOf['CAD Drawing URL']}${i + 3}`, column: 'CAD Drawing URL' });
  // the other cell holds a different drawing: left alone, but shown
  const otherCell = (m11 && cad && !mCad) ? 'CAD Drawing URL holds a different file: ' + nameOf(cad) : ((mCad && u11 && !m11) ? 'IMAGE URL11 holds a different file: ' + nameOf(u11) : '');
  const mid = adm.match(/\/products\/(\d+)/);
  const bases = []; if (clear.some(c => c.column === 'IMAGE URL11') && u11) bases.push(base(nameOf(u11))); if (clear.some(c => c.column === 'CAD Drawing URL') && cad) bases.push(base(nameOf(cad))); if (w.isFile) bases.push(base(w.file));
  const p = { old11: u11, oldCad: cad, row: i + 3, sku, id: mid ? mid[1] : null, drawing: w.file, note: w.note, reviewRow: w.reviewRow, clear: clear.filter(c => letterOf[c.column]), otherCell, bases: [...new Set(bases)] };
  if (!mid) { stats.noShopifyUrl++; sheetOnly.push(p); } else prods.push(p);
}
if (!prods.length) return [{ json: { tab: plan.sheet_name, noProducts: true, stats, sheetOnly } }];
const Q = `query Gallery($ids: [ID!]!) { nodes(ids: $ids) { ... on Product { id media(first: 20) { nodes { ... on MediaImage { id image { url } } } } metafield(namespace: "custom", key: "cad_drawing_url") { id value } } } }`;
const out = [];
for (let i = 0; i < prods.length; i += 8) {
  const chunk = prods.slice(i, i + 8);
  out.push({ json: { tab: plan.sheet_name, stats, sheetOnly: i === 0 ? sheetOnly : [], chunk, body: { query: Q, variables: { ids: chunk.map(p => 'gid://shopify/Product/' + p.id) } } } });
}
return out;

const j = $input.first().json;
const out = (j.sheetOnly || []).map(p => ({ json: { kind: 'product', tab: j.tab, ...p, liveOnShopify: false, where: 'sheet only (no Shopify link)' } }));
out.push({ json: { kind: 'summary', tab: j.tab, ...j.stats, checked: 0 } });
return out;

// For every affected product: is the wrong drawing in its Shopify gallery? Read only.
const baseUrl = (u) => String(u || '').split('?')[0];
const nameOf = (u) => { const l = baseUrl(u).split('/').pop() || ''; try { return decodeURIComponent(l); } catch (e) { return l; } };
const UUID = /_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(?=\.[A-Za-z0-9]+$)/i;
const base = (n) => String(n).replace(UUID, '').toLowerCase();
const reqs = $('Find Affected').all().map(i => i.json);
const stats = reqs[0].stats;
const out = [];
let checked = 0, live = 0, errors = 0;
$input.all().forEach((it, k) => {
  const rq = reqs[k]; const res = it.json;
  if (!rq) return;
  (rq.sheetOnly || []).forEach(p => out.push({ json: { kind: 'product', tab: rq.tab, ...p, liveOnShopify: false, where: 'sheet only (no Shopify link)' } }));
  if (res.error || (res.errors && res.errors.length) || !res.data || !Array.isArray(res.data.nodes)) {
    errors++;
    out.push({ json: { kind: 'error', tab: rq.tab, skus: rq.chunk.map(p => p.sku).join(', '), error: JSON.stringify(res.error || res.errors || res).slice(0, 200) } });
    return;
  }
  rq.chunk.forEach((p, i) => {
    const n = res.data.nodes[i];
    checked++;
    if (!n) { out.push({ json: { kind: 'product', tab: rq.tab, ...p, liveOnShopify: false, where: 'product not found on Shopify (deleted or wrong link)' } }); return; }
    const media = (n.media?.nodes || []).filter(m => m && m.id && m.image && m.image.url);
    const mediaIds = media.filter(m => p.bases.includes(base(nameOf(m.image.url)))).map(m => m.id);
    const meta = n.metafield || null;
    const metaMatch = !!(meta && meta.value && p.bases.includes(base(nameOf(meta.value))));
    const isLive = mediaIds.length > 0 || metaMatch;
    if (isLive) live++;
    out.push({ json: { kind: 'product', tab: rq.tab, ...p, mediaIds, metaId: meta ? meta.id : null, metaMatch, liveOnShopify: isLive, where: isLive ? 'live on Shopify (' + (mediaIds.length ? mediaIds.length + ' picture' : '') + (mediaIds.length && metaMatch ? ' + ' : '') + (metaMatch ? 'download button' : '') + ')' : 'not on the Shopify product' } });
  });
});
out.push({ json: { kind: 'summary', tab: stats.tab, ...stats, checked, live, shopifyReadErrors: errors } });
return out;

// Last step: report per drawing and per tab. dryRun true = nothing is changed.
const cfg = $('Config').first().json;
const review = $('Parse Review').first().json;
const all = $input.all().map(i => i.json);
const prods = all.filter(j => j.kind === 'product');
const sums = all.filter(j => j.kind === 'summary');
const errs = all.filter(j => j.kind === 'error');
if (!review.reviewOk) return [{ json: { applied: false, apply: false, problem: 'The review tab could not be read: ' + review.error + ' (check Config.reviewTab)' } }];
if (!review.wrong.length) return [{ json: { applied: false, apply: false, counts: review.counts, held: review.held, problem: 'No row to act on (all "no" rows are held: see held).' } }];
const shopifyErrors = errs.length;
const dryRun = cfg.dryRun !== false;
const perDrawing = review.wrong.map(w => {
  const mine = prods.filter(p => p.reviewRow === w.reviewRow);
  return { reviewRow: w.reviewRow, tab: w.tab, drawing: w.file, note: w.note, expectedProducts: w.products, foundInSheet: mine.length, liveOnShopify: mine.filter(p => p.liveOnShopify).length, notLive: mine.filter(p => !p.liveOnShopify).length };
});
const live = prods.filter(p => p.liveOnShopify);
const liveFiles = live.reduce((n, p) => n + (p.mediaIds || []).length, 0), liveMeta = live.filter(p => p.metaMatch).length;
const skuLists = (rows) => { const o = {}; rows.forEach(p => { o[p.tab] = (o[p.tab] ? o[p.tab] + ',' : '') + p.sku; }); return o; };
const cells = []; prods.forEach(p => (p.clear || []).forEach(c => cells.push(c.cell)));
const unknownTabs = [...new Set(review.wrong.map(w => w.tab).filter(t => !['2026Instock','Animal','Balustrade','Bathtub','Bench','BookMatchedSlabs','Carving','Columns','DoorSurround','Exterior-Wall-Decoration','Fireplace','Fountain','Lamppost','Marble+ Basin','Marble+ ConsoleTable','MarbleMedallion','MarbleRangeHood','MarbleSlab','Moulding','OutdoorCornice','Planter','Sink','Stairs','Statue','StoneMosaicTile','Table','Vanity','Wainscoting','Wall-Coverings','WindowSurround'].includes(t)))];
const notFound = perDrawing.filter(d => d.foundInSheet === 0).map(d => d.tab + ' / ' + d.drawing);
const yesMode = String(cfg.mode || '').toLowerCase() === 'yes';
const needs = prods.filter(p => p.id && (!(p.mediaIds || []).length || !p.metaMatch));
const apply = !yesMode && !dryRun && shopifyErrors === 0 && unknownTabs.length === 0 && cells.length > 0;
return [{ json: {
  dryRun, applied: false, apply,
  blockedBecause: !dryRun && shopifyErrors > 0 ? 'a Shopify read failed, so nothing was changed; run again' : (!dryRun && unknownTabs.length ? 'a tab name in the review tab is not a sheet tab, so nothing was changed' : undefined),
  reviewCounts: review.counts,
  wrongDrawings: review.wrong.length, productsInSheet: prods.length, liveOnShopify: live.length, galleryPicturesToDetach: liveFiles, metafieldsToDelete: liveMeta, notLiveOrSheetOnly: prods.length - live.length,
  cellsToClear: cells.length, shopifyReadErrors: shopifyErrors,
  heldCount: (review.held || []).length,
  held: (review.held || []).map(h => ({ reviewRow: h.reviewRow, tab: h.tab, drawing: h.file, skus: h.skus.join(','), reason: h.reason, note: h.note })),
  yesModeReport: yesMode ? { meaning: 'drawings marked yes: is the correct CAD on each product on Shopify (gallery picture and download button)?', productsOnShopify: prods.filter(p => p.id).length, fullyThere: prods.filter(p => p.id && (p.mediaIds || []).length && p.metaMatch).length, missingPicture: prods.filter(p => p.id && !(p.mediaIds || []).length).length, missingButton: prods.filter(p => p.id && !p.metaMatch).length, sheetOnlyNotCreatedYet: prods.filter(p => !p.id).length, needUpdateSkusByTab: skuLists(needs) } : undefined,
  tabsNotRecognised: unknownTabs,
  drawingsNotFoundInSheet: notFound,
  perDrawing,
  liveSkusByTab: skuLists(live),
  notLiveSkusByTab: skuLists(prods.filter(p => !p.liveOnShopify)),
  otherCellNotes: prods.filter(p => p.otherCell).slice(0, 30).map(p => ({ tab: p.tab, sku: p.sku, note: p.otherCell })),
  perTab: sums.map(s => ({ tab: s.tab, rows: s.rows, affected: s.affected, live: s.live, noShopifyUrl: s.noShopifyUrl })),
  errorDetails: errs.slice(0, 10),
  _log: apply ? prods.map(p => ({ live: !!p.liveOnShopify, tab: p.tab, row: p.row, sku: p.sku, drawing: p.drawing, note: p.note, old11: p.old11 || '', oldCad: p.oldCad || '' })) : [],
  _removals: apply ? live.map(p => ({ tab: p.tab, sku: p.sku, id: p.id, mediaIds: p.mediaIds || [], metaId: p.metaMatch ? p.metaId : null, cells: (p.clear || []).map(c => c.cell) })) : [],
  _cellsNow: apply ? prods.filter(p => !p.liveOnShopify).flatMap(p => (p.clear || []).map(c => c.cell)) : []
} }];

// One request per live product: detach the wrong picture from the product (the shared file stays for other products) and delete the CAD download-button metafield.
const rem = $input.first().json._removals || [];
const out = rem.map(r => {
  const vars = {}; const decl = []; const parts = [];
  if (r.mediaIds.length) { decl.push('$files: [FileUpdateInput!]!'); vars.files = r.mediaIds.map(id => ({ id, referencesToRemove: ['gid://shopify/Product/' + r.id] })); parts.push('fileUpdate(files: $files) { files { id } userErrors { field message } }'); }
  if (r.metaId) { decl.push('$mf: [MetafieldIdentifierInput!]!'); vars.mf = [{ ownerId: 'gid://shopify/Product/' + r.id, namespace: 'custom', key: 'cad_drawing_url' }]; parts.push('metafieldsDelete(metafields: $mf) { deletedMetafields { key } userErrors { field message } }'); }
  return { json: { ...r, body: { query: 'mutation R(' + decl.join(', ') + ') { ' + parts.join(' ') + ' }', variables: vars } } };
});
// no live product: one harmless request so the next steps still run
if (!out.length) out.push({ json: { noop: true, cells: [], body: { query: '{ shop { name } }' } } });
return out;

// Which products were really changed on Shopify. Their sheet cells are cleared next; failed ones keep their cells so a re-run finds them again.
const reqs = $('Build Shopify Removals').all().map(i => i.json);
const rep = $('Final Report').first().json;
const cells = [...(rep._cellsNow || [])];
const ok = [], failed = [];
$input.all().forEach((it, k) => {
  const rq = reqs[k]; const r = it.json;
  if (!rq || rq.noop) return;
  const ue = [].concat(r.data?.fileUpdate?.userErrors || [], r.data?.metafieldsDelete?.userErrors || []);
  if (r.error || (r.errors && r.errors.length) || !r.data || ue.length) { failed.push({ tab: rq.tab, sku: rq.sku, error: JSON.stringify(r.error || r.errors || ue || r).slice(0, 250) }); return; }
  ok.push(rq.sku); rq.cells.forEach(c => cells.push(c));
});
// Log of everything that is about to be cleared (old values), so nothing is lost.
const okSet = new Set(ok);
const when = new Date().toISOString();
const log = (rep._log || []).filter(l => !l.live || okSet.has(l.sku)).map(l => [when, l.tab, l.row, l.sku, l.drawing, l.note, l.old11, l.oldCad]);
return [{ json: { cells, shopifyOk: ok.length, shopifyFailed: failed.length, failed, sheetOnlyCells: (rep._cellsNow || []).length, log } }];

const lg = $input.first().json;
if (lg.error || !lg.updates) throw new Error('The log of old values could not be written, so nothing was cleared in the sheet: ' + JSON.stringify(lg.error || lg).slice(0, 300));
const cells = $('Collect Results').first().json.cells || [];
const out = [];
for (let i = 0; i < cells.length; i += 200) out.push({ json: { n: cells.slice(i, i + 200).length, body: { ranges: cells.slice(i, i + 200) } } });
return out;

// Result of the real run. Shopify first, then the sheet.
const reqs = $('Build Clear Request').all().map(i => i.json);
const col = $('Collect Results').first().json;
let cleared = 0, failed = 0; const errors = [];
$input.all().forEach((it, k) => {
  const r = it.json;
  if (r.error || !r.clearedRanges) { failed += (reqs[k] ? reqs[k].n : 0); errors.push(JSON.stringify(r.error || r).slice(0, 200)); }
  else cleared += r.clearedRanges.length;
});
return [{ json: { applied: true, shopifyProductsChanged: col.shopifyOk, shopifyFailed: col.shopifyFailed, shopifyFailures: col.failed, sheetOnlyCellsCleared: col.sheetOnlyCells, sheetCellsCleared: cleared, sheetCellsFailed: failed, errors, note: 'Failed products keep their sheet cells: fix the cause and run again.' } }];
